//! C API over [`buildfs::vfs::Vfs`], linked into the FSKit extension.
//!
//! Conventions:
//! - Every fallible function returns 0 or a positive errno.
//! - Names are byte strings with explicit lengths and must be UTF-8
//!   (`EILSEQ` otherwise).
//! - Out-pointers are written only on success.
//! - Mutating calls return post-operation attributes, which FSKit's reply
//!   objects need, so the caller doesn't make extra `getattr` round trips.
//! - Panics are caught at the boundary and reported as `EIO`.
//!
//! The header `fskit/Extension/buildfs_ffi.h` is generated by `build.rs`.

use std::ffi::{CStr, c_char, c_void};
use std::io::Write;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::Path;
use std::sync::{Arc, OnceLock};
use std::time::Duration;

use buildfs::meta::{FLAG_ARCHIVE, FLAG_HIDDEN, Ino, Inode, Kind};
use buildfs::vfs::{Caller, NewNode, Options, Vfs};
use embednfs::{FsError, SetAttrs, SetTime, Timestamp, XattrSetMode};

/// An open store. Opaque to C.
pub struct BfsVfs {
    vfs: Arc<Vfs>,
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

// Item kinds. The values match FSKit's `FSItemType` raw values.
pub const BFS_KIND_FILE: u32 = 1;
pub const BFS_KIND_DIR: u32 = 2;
pub const BFS_KIND_SYMLINK: u32 = 3;
pub const BFS_KIND_FIFO: u32 = 4;
pub const BFS_KIND_CHAR: u32 = 5;
pub const BFS_KIND_BLOCK: u32 = 6;
pub const BFS_KIND_SOCKET: u32 = 7;

/// Largest xattr value accepted (`E2BIG` beyond).
pub const BFS_MAX_XATTR_SIZE: u64 = 64 << 20;
/// Largest file size.
pub const BFS_MAX_FILE_SIZE: u64 = 1 << 50;
const _: () = assert!(BFS_MAX_FILE_SIZE == buildfs::vfs::MAX_FILE_SIZE);

/// The root directory's inode number.
pub const BFS_ROOT_INO: u64 = 1;
const _: () = assert!(BFS_ROOT_INO == buildfs::meta::ROOT_INO);

// BSD file flags (`st_flags`) the store can represent.
pub const BFS_UF_HIDDEN: u32 = 0x0000_8000;
pub const BFS_SF_ARCHIVED: u32 = 0x0001_0000;
/// Document-tracking flag macOS sets on copies; accepted and dropped.
pub const BFS_UF_TRACKED: u32 = 0x0000_0040;

// `BfsSetattr::valid` bits.
pub const BFS_SET_SIZE: u32 = 1 << 0;
pub const BFS_SET_MODE: u32 = 1 << 1;
pub const BFS_SET_UID: u32 = 1 << 2;
pub const BFS_SET_GID: u32 = 1 << 3;
pub const BFS_SET_FLAGS: u32 = 1 << 4;
pub const BFS_SET_ATIME: u32 = 1 << 5;
pub const BFS_SET_MTIME: u32 = 1 << 6;
pub const BFS_SET_BTIME: u32 = 1 << 7;

// `bfs_set_xattr` modes.
pub const BFS_XATTR_SET: u32 = 0;
pub const BFS_XATTR_CREATE: u32 = 1;
pub const BFS_XATTR_REPLACE: u32 = 2;

// Log levels passed to the log callback.
pub const BFS_LOG_TRACE: i32 = 0;
pub const BFS_LOG_DEBUG: i32 = 1;
pub const BFS_LOG_INFO: i32 = 2;
pub const BFS_LOG_WARN: i32 = 3;
pub const BFS_LOG_ERROR: i32 = 4;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/// Same layout as `struct timespec` on 64-bit Darwin.
#[repr(C)]
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct BfsTime {
    pub sec: i64,
    pub nsec: i64,
}

#[repr(C)]
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct BfsAttr {
    pub ino: u64,
    /// Parent directory (directories only; the root's parent is itself).
    pub parent: u64,
    pub size: u64,
    /// Bytes the item occupies in the store (what `du` shows).
    pub space_used: u64,
    /// Strictly increases on every change to the item.
    pub change: u64,
    /// One of `BFS_KIND_*`.
    pub kind: u32,
    /// Permission bits only (`0o7777`).
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub nlink: u32,
    /// BSD `st_flags` (`BFS_UF_HIDDEN`, `BFS_SF_ARCHIVED`).
    pub flags: u32,
    pub rdev_major: u32,
    pub rdev_minor: u32,
    pub atime: BfsTime,
    pub mtime: BfsTime,
    pub ctime: BfsTime,
    pub btime: BfsTime,
}

/// Attributes to set; only fields whose `BFS_SET_*` bit is in `valid` are used.
#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
pub struct BfsSetattr {
    pub valid: u32,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub flags: u32,
    pub size: u64,
    pub atime: BfsTime,
    pub mtime: BfsTime,
    pub btime: BfsTime,
}

/// The process asking for an operation.
#[repr(C)]
pub struct BfsCaller {
    pub uid: u32,
    pub gid: u32,
    /// Supplementary groups (may be null when `ngroups` is 0).
    pub groups: *const u32,
    pub ngroups: usize,
}

/// Store options. Zero or negative fields mean "default".
#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
pub struct BfsOptions {
    /// Compress files after this many ms without writes; 0 = default (15 s),
    /// negative = never compress in the background.
    pub compress_after_ms: i64,
    /// Background compression threads; 0 = default.
    pub compress_workers: u32,
    /// zstd level; 0 = default.
    pub zstd_level: i32,
    /// Decompressed-chunk cache size; 0 = default.
    pub cache_bytes: u64,
}

#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
pub struct BfsStatfs {
    pub block_size: u64,
    pub total_bytes: u64,
    pub free_bytes: u64,
    pub avail_bytes: u64,
    pub total_files: u64,
    pub free_files: u64,
}

/// A byte buffer allocated by this library; release it with `bfs_buf_free`.
#[repr(C)]
#[derive(Debug)]
pub struct BfsBuf {
    pub ptr: *mut u8,
    pub len: usize,
}

#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
pub struct BfsCompressStats {
    pub compacted: u64,
    pub inlined: u64,
    pub rehydrated: u64,
    pub logical_bytes: u64,
    pub stored_bytes: u64,
    pub dedup_chunks: u64,
    pub dedup_bytes: u64,
}

/// Receives one log line (`msg` is not NUL-terminated).
pub type BfsLogFn = extern "C" fn(ctx: *mut c_void, level: i32, msg: *const u8, len: usize);

/// Receives one directory entry; return false to stop. `attr` is null unless
/// attributes were requested.
pub type BfsDirEmit = extern "C" fn(
    ctx: *mut c_void,
    name: *const u8,
    len: usize,
    ino: u64,
    kind: u32,
    cookie: u64,
    attr: *const BfsAttr,
) -> bool;

// ---------------------------------------------------------------------------
// Plumbing
// ---------------------------------------------------------------------------

type R<T> = Result<T, i32>;

fn errno(e: FsError) -> i32 {
    match e {
        FsError::PermissionDenied => libc::EPERM,
        FsError::NotFound => libc::ENOENT,
        FsError::AccessDenied => libc::EACCES,
        FsError::AlreadyExists => libc::EEXIST,
        FsError::CrossDevice => libc::EXDEV,
        FsError::NotDirectory => libc::ENOTDIR,
        FsError::IsDirectory => libc::EISDIR,
        FsError::InvalidInput => libc::EINVAL,
        FsError::FileTooLarge => libc::EFBIG,
        FsError::NoSpace => libc::ENOSPC,
        FsError::ReadOnly => libc::EROFS,
        FsError::NameTooLong => libc::ENAMETOOLONG,
        FsError::NotEmpty => libc::ENOTEMPTY,
        FsError::Stale => libc::ESTALE,
        FsError::Unsupported => libc::ENOTSUP,
        FsError::BadHandle => libc::EBADF,
        FsError::Ok | FsError::Io | FsError::ServerFault => libc::EIO,
    }
}

/// xattr calls report a missing attribute as `ENOATTR`, not `ENOENT`.
fn xattr_errno(e: FsError) -> i32 {
    match e {
        FsError::NotFound => libc::ENOATTR,
        e => errno(e),
    }
}

trait Errno<T> {
    fn en(self) -> R<T>;
}
impl<T> Errno<T> for Result<T, FsError> {
    fn en(self) -> R<T> {
        self.map_err(errno)
    }
}

/// Runs `f`, turning panics into `EIO`.
fn guard(f: impl FnOnce() -> R<()>) -> i32 {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(())) => 0,
        Ok(Err(e)) => e,
        Err(_) => {
            tracing::error!("panic in buildfs-ffi call");
            libc::EIO
        }
    }
}

/// # Safety
/// `v` is null or a pointer returned by `bfs_open` and not yet closed.
unsafe fn vfs<'a>(v: *const BfsVfs) -> R<&'a Vfs> {
    // SAFETY: guaranteed by the caller.
    let h = unsafe { v.as_ref() }.ok_or(libc::EINVAL)?;
    Ok(&h.vfs)
}

/// # Safety
/// `ptr` is valid for reads of `len` bytes, or `len` is 0.
unsafe fn bytes<'a>(ptr: *const u8, len: usize) -> R<&'a [u8]> {
    if len == 0 {
        return Ok(&[]);
    }
    if ptr.is_null() {
        return Err(libc::EINVAL);
    }
    // SAFETY: guaranteed by the caller.
    Ok(unsafe { std::slice::from_raw_parts(ptr, len) })
}

/// Longest name in bytes (`NAME_MAX`).
pub const BFS_NAME_MAX: usize = 255;

/// A UTF-8 string of any length (symlink targets).
///
/// # Safety
/// As for [`bytes`].
unsafe fn text<'a>(ptr: *const u8, len: usize) -> R<&'a str> {
    // SAFETY: guaranteed by the caller.
    let b = unsafe { bytes(ptr, len) }?;
    std::str::from_utf8(b).map_err(|_| libc::EILSEQ)
}

/// A file or xattr name. Over-long names are refused here: FSKit passes
/// them through to lookups, which would otherwise say ENOENT.
///
/// # Safety
/// As for [`bytes`].
unsafe fn name<'a>(ptr: *const u8, len: usize) -> R<&'a str> {
    if len > BFS_NAME_MAX {
        return Err(libc::ENAMETOOLONG);
    }
    // SAFETY: guaranteed by the caller.
    unsafe { text(ptr, len) }
}

/// # Safety
/// `c` is null or points to a valid `BfsCaller` whose `groups` is valid for
/// `ngroups` elements.
unsafe fn caller(c: *const BfsCaller) -> R<Caller> {
    // SAFETY: guaranteed by the caller.
    let c = unsafe { c.as_ref() }.ok_or(libc::EINVAL)?;
    let groups = if c.ngroups == 0 || c.groups.is_null() {
        Vec::new()
    } else {
        // SAFETY: guaranteed by the caller.
        unsafe { std::slice::from_raw_parts(c.groups, c.ngroups) }.to_vec()
    };
    Ok(Caller {
        uid: c.uid,
        gid: c.gid,
        groups,
    })
}

/// Writes `value` through `out` if it is non-null.
///
/// # Safety
/// `out` is null or valid for writes.
unsafe fn put<T>(out: *mut T, value: T) {
    // SAFETY: guaranteed by the caller.
    if let Some(o) = unsafe { out.as_mut() } {
        *o = value;
    }
}

fn kind_code(k: Kind) -> u32 {
    match k {
        Kind::File => BFS_KIND_FILE,
        Kind::Dir => BFS_KIND_DIR,
        Kind::Symlink => BFS_KIND_SYMLINK,
        Kind::Fifo => BFS_KIND_FIFO,
        Kind::CharDev => BFS_KIND_CHAR,
        Kind::BlockDev => BFS_KIND_BLOCK,
        Kind::Socket => BFS_KIND_SOCKET,
    }
}

fn time(t: buildfs::meta::Ts) -> BfsTime {
    BfsTime {
        sec: t.sec,
        nsec: i64::from(t.nsec),
    }
}

fn attr(vfs: &Vfs, ino: Ino, i: &Inode) -> BfsAttr {
    let mut flags = 0;
    if i.flags & FLAG_HIDDEN != 0 {
        flags |= BFS_UF_HIDDEN;
    }
    if i.flags & FLAG_ARCHIVE != 0 {
        flags |= BFS_SF_ARCHIVED;
    }
    BfsAttr {
        ino,
        parent: i.parent,
        size: i.size,
        space_used: vfs.space_used(ino, i),
        change: i.change,
        kind: kind_code(i.kind),
        mode: i.mode,
        uid: i.uid,
        gid: i.gid,
        nlink: i.nlink,
        flags,
        rdev_major: i.rdev.0,
        rdev_minor: i.rdev.1,
        atime: time(i.atime),
        mtime: time(i.mtime),
        ctime: time(i.ctime),
        btime: time(i.btime),
    }
}

fn getattr(vfs: &Vfs, ino: Ino) -> R<BfsAttr> {
    let i = vfs.getattr(ino).en()?;
    Ok(attr(vfs, ino, &i))
}

/// Attributes after an operation that may have freed the inode: the current
/// ones if it still exists, otherwise the old ones with no links left.
fn after_unlink(vfs: &Vfs, ino: Ino, before: BfsAttr) -> BfsAttr {
    getattr(vfs, ino).unwrap_or(BfsAttr { nlink: 0, ..before })
}

fn set_time(t: BfsTime) -> R<SetTime> {
    let nanos = u32::try_from(t.nsec)
        .ok()
        .filter(|&n| n < 1_000_000_000)
        .ok_or(libc::EINVAL)?;
    Ok(SetTime::Client(Timestamp {
        seconds: t.sec,
        nanos,
    }))
}

fn setattrs(s: &BfsSetattr) -> R<SetAttrs> {
    let has = |bit| s.valid & bit != 0;
    let mut a = SetAttrs::default();
    if has(BFS_SET_SIZE) {
        a.size = Some(s.size);
    }
    if has(BFS_SET_MODE) {
        a.mode = Some(s.mode & 0o7777);
    }
    if has(BFS_SET_UID) {
        a.uid = Some(s.uid);
    }
    if has(BFS_SET_GID) {
        a.gid = Some(s.gid);
    }
    if has(BFS_SET_FLAGS) {
        if s.flags & !(BFS_UF_HIDDEN | BFS_SF_ARCHIVED | BFS_UF_TRACKED) != 0 {
            return Err(libc::ENOTSUP);
        }
        a.hidden = Some(s.flags & BFS_UF_HIDDEN != 0);
        a.archive = Some(s.flags & BFS_SF_ARCHIVED != 0);
    }
    if has(BFS_SET_ATIME) {
        a.atime = Some(set_time(s.atime)?);
    }
    if has(BFS_SET_MTIME) {
        a.mtime = Some(set_time(s.mtime)?);
    }
    if has(BFS_SET_BTIME) {
        a.birthtime = Some(set_time(s.btime)?);
    }
    Ok(a)
}

fn into_buf(v: Vec<u8>) -> BfsBuf {
    let b = v.into_boxed_slice();
    let len = b.len();
    BfsBuf {
        ptr: Box::into_raw(b).cast::<u8>(),
        len,
    }
}

// ---------------------------------------------------------------------------
// Logging
// ---------------------------------------------------------------------------

#[derive(Clone, Copy)]
struct LogSink {
    f: BfsLogFn,
    ctx: usize,
}

struct LineWriter {
    sink: LogSink,
    level: i32,
    buf: Vec<u8>,
}

impl Write for LineWriter {
    fn write(&mut self, b: &[u8]) -> std::io::Result<usize> {
        self.buf.extend_from_slice(b);
        Ok(b.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl Drop for LineWriter {
    fn drop(&mut self) {
        let msg = self.buf.trim_ascii_end();
        if !msg.is_empty() {
            (self.sink.f)(self.sink.ctx as *mut c_void, self.level, msg.as_ptr(), msg.len());
        }
    }
}

impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for LogSink {
    type Writer = LineWriter;
    fn make_writer(&'a self) -> LineWriter {
        self.make_line(BFS_LOG_INFO)
    }
    fn make_writer_for(&'a self, meta: &tracing::Metadata<'_>) -> LineWriter {
        let level = match *meta.level() {
            tracing::Level::TRACE => BFS_LOG_TRACE,
            tracing::Level::DEBUG => BFS_LOG_DEBUG,
            tracing::Level::INFO => BFS_LOG_INFO,
            tracing::Level::WARN => BFS_LOG_WARN,
            tracing::Level::ERROR => BFS_LOG_ERROR,
        };
        self.make_line(level)
    }
}

impl LogSink {
    fn make_line(&self, level: i32) -> LineWriter {
        LineWriter {
            sink: *self,
            level,
            buf: Vec::with_capacity(128),
        }
    }
}

static LOGGER: OnceLock<()> = OnceLock::new();

/// Routes the core's log output to `f`. `filter` is an `EnvFilter`
/// directive such as `"info"` or `"buildfs=debug"` (null: `"info"`).
/// Only the first call has an effect; returns `EALREADY` afterwards.
///
/// # Safety
/// `filter` is null or a NUL-terminated string. `f` and `ctx` stay valid
/// for the life of the process.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_set_logger(f: BfsLogFn, ctx: *mut c_void, filter: *const c_char) -> i32 {
    let filter = if filter.is_null() {
        "info".to_owned()
    } else {
        // SAFETY: guaranteed by the caller.
        unsafe { CStr::from_ptr(filter) }.to_string_lossy().into_owned()
    };
    let mut installed = false;
    let _ = LOGGER.get_or_init(|| {
        let sink = LogSink { f, ctx: ctx as usize };
        installed = tracing_subscriber::fmt()
            .with_writer(sink)
            .with_ansi(false)
            .without_time()
            .with_level(false)
            .with_env_filter(tracing_subscriber::EnvFilter::new(filter))
            .try_init()
            .is_ok();
    });
    if installed { 0 } else { libc::EALREADY }
}

// ---------------------------------------------------------------------------
// Lifecycle
// ---------------------------------------------------------------------------

/// Opens (creating if needed) the store in `store_dir`, replaying its WAL,
/// and starts the background flusher and compactor threads.
///
/// # Safety
/// `store_dir` is a NUL-terminated path; `opts` is null or valid; `out` is
/// valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_open(
    store_dir: *const c_char,
    opts: *const BfsOptions,
    out: *mut *mut BfsVfs,
) -> i32 {
    guard(|| {
        if store_dir.is_null() || out.is_null() {
            return Err(libc::EINVAL);
        }
        // SAFETY: guaranteed by the caller.
        let dir = unsafe { CStr::from_ptr(store_dir) }.to_str().map_err(|_| libc::EILSEQ)?;
        // SAFETY: guaranteed by the caller.
        let o = unsafe { opts.as_ref() }.copied().unwrap_or_default();
        let mut options = Options::default();
        match o.compress_after_ms {
            0 => {}
            ms if ms < 0 => options.compress_after = None,
            ms => options.compress_after = Some(Duration::from_millis(ms.unsigned_abs())),
        }
        if o.compress_workers > 0 {
            options.compress_workers = o.compress_workers as usize;
        }
        if o.zstd_level != 0 {
            options.level = o.zstd_level;
        }
        if o.cache_bytes > 0 {
            options.cache_bytes = usize::try_from(o.cache_bytes).unwrap_or(usize::MAX);
        }
        match buildfs::raise_fd_limit() {
            Ok(n) => tracing::info!("open file limit: {n}"),
            Err(e) => tracing::warn!("could not raise the open file limit: {e}"),
        }
        let vfs = Vfs::open_with(Path::new(dir), options).map_err(|e| {
            tracing::error!("opening store {dir} failed: {e:#}");
            libc::EIO
        })?;
        tracing::info!("opened store {dir}");
        // SAFETY: `out` checked non-null above; guaranteed valid by the caller.
        unsafe { *out = Box::into_raw(Box::new(BfsVfs { vfs })) };
        Ok(())
    })
}

/// Stops background work, makes metadata durable and frees the handle.
///
/// # Safety
/// `v` is null or a handle from `bfs_open` that is not used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_close(v: *mut BfsVfs) {
    if v.is_null() {
        return;
    }
    // SAFETY: guaranteed by the caller; ownership returns to Rust here.
    let h = unsafe { Box::from_raw(v) };
    let _ = guard(|| {
        h.vfs.shutdown();
        tracing::info!("store closed");
        Ok(())
    });
    drop(h);
}

/// Makes all metadata changes so far durable (group-committed).
///
/// # Safety
/// `v` is a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_sync(v: *const BfsVfs) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        unsafe { vfs(v) }?.sync_metadata();
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Lookups
// ---------------------------------------------------------------------------

/// # Safety
/// `v` is a live handle; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_getattr(v: *const BfsVfs, ino: u64, out: *mut BfsAttr) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let a = getattr(vfs, ino)?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, a) };
        Ok(())
    })
}

/// Looks up `name` in `dir` and returns the child's attributes.
///
/// # Safety
/// `v` is a live handle; `name` is valid for `len` bytes; `out` is valid
/// for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_lookup(
    v: *const BfsVfs,
    dir: u64,
    name: *const u8,
    len: usize,
    out: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name) = unsafe { (vfs(v)?, self::name(name, len)?) };
        let (ino, inode) = vfs.lookup_attr(dir, name).en()?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, attr(vfs, ino, &inode)) };
        Ok(())
    })
}

/// Lists `dir` starting after `cookie` (0 = from the start), calling `emit`
/// for each entry until it returns false or the directory ends. Cookies are
/// stable under concurrent changes and never reused; pass the last one
/// emitted to resume.
///
/// # Safety
/// `v` is a live handle; `emit` is safe to call with `ctx`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_readdir(
    v: *const BfsVfs,
    dir: u64,
    cookie: u64,
    with_attrs: bool,
    emit: BfsDirEmit,
    ctx: *mut c_void,
) -> i32 {
    const BATCH: usize = 128;
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let mut cookie = cookie;
        loop {
            // Attributes are always read: entries need their kind.
            let (items, eof) = vfs.readdir(dir, cookie, BATCH, true).en()?;
            for it in &items {
                let Some(inode) = it.attrs.as_ref() else { continue };
                // Full attributes only on request: space_used costs a stat
                // of the data file for uncompressed files.
                let a = with_attrs.then(|| attr(vfs, it.ino, inode));
                let ap: *const BfsAttr = a.as_ref().map_or(std::ptr::null(), |a| a);
                let n = it.name.as_bytes();
                if !emit(ctx, n.as_ptr(), n.len(), it.ino, kind_code(inode.kind), it.cookie, ap) {
                    return Ok(());
                }
                cookie = it.cookie;
            }
            if eof || items.is_empty() {
                return Ok(());
            }
        }
    })
}

/// # Safety
/// `v` is a live handle; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_readlink(v: *const BfsVfs, ino: u64, out: *mut BfsBuf) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let target = vfs.readlink(ino).en()?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, into_buf(target.into_bytes())) };
        Ok(())
    })
}

/// # Safety
/// `v` is a live handle; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_statfs(v: *const BfsVfs, out: *mut BfsStatfs) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let st = vfs.statfs().en()?;
        #[allow(clippy::unnecessary_cast, reason = "statvfs field widths differ across platforms")]
        let (frsize, blocks, bfree, bavail) = (
            st.f_frsize as u64,
            st.f_blocks as u64,
            st.f_bfree as u64,
            st.f_bavail as u64,
        );
        let s = BfsStatfs {
            block_size: frsize,
            total_bytes: blocks * frsize,
            free_bytes: bfree * frsize,
            avail_bytes: bavail * frsize,
            total_files: 1 << 40,
            free_files: 1 << 39,
        };
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, s) };
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Namespace
// ---------------------------------------------------------------------------

/// Creates `name` in `dir`. `kind` is a `BFS_KIND_*`; `target` is the
/// symlink target (symlinks only); `rdev_*` are used for device nodes.
/// `init` (nullable) holds the initial attributes; its mode is applied, its
/// uid/gid are not (owner is the caller, group comes from `dir`).
///
/// # Safety
/// `v` is a live handle; pointers are valid for their lengths; out-pointers
/// are null or valid for writes.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments, reason = "flat C ABI")]
pub unsafe extern "C" fn bfs_create(
    v: *const BfsVfs,
    who: *const BfsCaller,
    dir: u64,
    name: *const u8,
    len: usize,
    kind: u32,
    rdev_major: u32,
    rdev_minor: u32,
    init: *const BfsSetattr,
    target: *const u8,
    target_len: usize,
    out_item: *mut BfsAttr,
    out_dir: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, who, name) = unsafe { (vfs(v)?, caller(who)?, self::name(name, len)?) };
        let node = match kind {
            BFS_KIND_FILE => NewNode::File,
            BFS_KIND_DIR => NewNode::Dir,
            BFS_KIND_SYMLINK => {
                // SAFETY: guaranteed by the caller.
                NewNode::Symlink(unsafe { text(target, target_len) }?.to_owned())
            }
            BFS_KIND_FIFO => NewNode::Fifo,
            BFS_KIND_SOCKET => NewNode::Socket,
            BFS_KIND_CHAR => NewNode::CharDev(rdev_major, rdev_minor),
            BFS_KIND_BLOCK => NewNode::BlockDev(rdev_major, rdev_minor),
            _ => return Err(libc::EINVAL),
        };
        // SAFETY: guaranteed by the caller.
        let mut initial = match unsafe { init.as_ref() } {
            Some(s) => setattrs(s)?,
            None => SetAttrs::default(),
        };
        // Ownership of new items follows BSD rules, not the request.
        initial.uid = None;
        initial.gid = None;
        let (ino, inode) = vfs.create(&who, dir, name, node, &initial).en()?;
        let item = attr(vfs, ino, &inode);
        let d = getattr(vfs, dir)?;
        // SAFETY: guaranteed by the caller.
        unsafe {
            put(out_item, item);
            put(out_dir, d);
        }
        Ok(())
    })
}

/// Adds the hard link `dir/name` to `ino`.
///
/// # Safety
/// As for `bfs_create`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_link(
    v: *const BfsVfs,
    ino: u64,
    dir: u64,
    name: *const u8,
    len: usize,
    out_item: *mut BfsAttr,
    out_dir: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name) = unsafe { (vfs(v)?, self::name(name, len)?) };
        vfs.link(ino, dir, name).en()?;
        let (item, d) = (getattr(vfs, ino)?, getattr(vfs, dir)?);
        // SAFETY: guaranteed by the caller.
        unsafe {
            put(out_item, item);
            put(out_dir, d);
        }
        Ok(())
    })
}

/// Removes `dir/name` (file or empty directory). `out_item` receives the
/// item's attributes afterwards; if that was its last link and it isn't
/// open, the inode is gone and `nlink` is 0.
///
/// # Safety
/// As for `bfs_create`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_remove(
    v: *const BfsVfs,
    dir: u64,
    name: *const u8,
    len: usize,
    out_item: *mut BfsAttr,
    out_dir: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name) = unsafe { (vfs(v)?, self::name(name, len)?) };
        let ino = vfs.lookup(dir, name).en()?;
        let before = getattr(vfs, ino)?;
        vfs.remove(dir, name).en()?;
        let item = after_unlink(vfs, ino, before);
        let d = getattr(vfs, dir)?;
        // SAFETY: guaranteed by the caller.
        unsafe {
            put(out_item, item);
            put(out_dir, d);
        }
        Ok(())
    })
}

/// Renames `from_dir/from` to `to_dir/to`, replacing an existing target.
/// If a target was replaced, `*out_replaced` is set to true and `out_over`
/// receives its attributes afterwards (`nlink` 0 if it was freed).
///
/// # Safety
/// As for `bfs_create`.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments, reason = "flat C ABI")]
pub unsafe extern "C" fn bfs_rename(
    v: *const BfsVfs,
    from_dir: u64,
    from: *const u8,
    from_len: usize,
    to_dir: u64,
    to: *const u8,
    to_len: usize,
    out_item: *mut BfsAttr,
    out_from_dir: *mut BfsAttr,
    out_to_dir: *mut BfsAttr,
    out_over: *mut BfsAttr,
    out_replaced: *mut bool,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, from, to) = unsafe { (vfs(v)?, name(from, from_len)?, name(to, to_len)?) };
        let src = vfs.lookup(from_dir, from).en()?;
        let over = match vfs.lookup(to_dir, to) {
            Ok(o) if o != src => Some((o, getattr(vfs, o)?)),
            Ok(_) | Err(FsError::NotFound) => None,
            Err(e) => return Err(errno(e)),
        };
        vfs.rename(from_dir, from, to_dir, to).en()?;
        let item = getattr(vfs, src)?;
        let fd = getattr(vfs, from_dir)?;
        let td = getattr(vfs, to_dir)?;
        // SAFETY: guaranteed by the caller.
        unsafe {
            put(out_item, item);
            put(out_from_dir, fd);
            put(out_to_dir, td);
            put(out_replaced, over.is_some());
            if let Some((o, before)) = over {
                put(out_over, after_unlink(vfs, o, before));
            }
        }
        Ok(())
    })
}

// ---------------------------------------------------------------------------
// Attributes and data
// ---------------------------------------------------------------------------

/// # Safety
/// `v` is a live handle; `who` and `req` are valid; `out` is null or valid
/// for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_setattr(
    v: *const BfsVfs,
    who: *const BfsCaller,
    ino: u64,
    req: *const BfsSetattr,
    out: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, who) = unsafe { (vfs(v)?, caller(who)?) };
        // SAFETY: guaranteed by the caller.
        let req = unsafe { req.as_ref() }.ok_or(libc::EINVAL)?;
        let set = setattrs(req)?;
        let inode = vfs.setattr(&who, ino, &set).en()?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, attr(vfs, ino, &inode)) };
        Ok(())
    })
}

/// Reads up to `len` bytes at `offset` into `buf`; `*nread` is the count
/// (short only at end of file).
///
/// # Safety
/// `v` is a live handle; `buf` is valid for writes of `len` bytes; `nread`
/// is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_read(
    v: *const BfsVfs,
    ino: u64,
    offset: u64,
    buf: *mut u8,
    len: usize,
    nread: *mut usize,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        if buf.is_null() && len > 0 {
            return Err(libc::EINVAL);
        }
        let count = u32::try_from(len).unwrap_or(u32::MAX);
        let (data, _eof) = vfs.read(ino, offset, count).en()?;
        let n = data.len().min(len);
        if n > 0 {
            // SAFETY: `buf` is valid for `len >= n` bytes (caller) and does
            // not overlap our freshly allocated `data`.
            unsafe { std::ptr::copy_nonoverlapping(data.as_ptr(), buf, n) };
        }
        // SAFETY: guaranteed by the caller.
        unsafe { put(nread, n) };
        Ok(())
    })
}

/// Writes `len` bytes at `offset`; `out` receives the attributes afterwards.
///
/// # Safety
/// `v` is a live handle; `buf` is valid for `len` bytes; out-pointers are
/// null or valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_write(
    v: *const BfsVfs,
    ino: u64,
    offset: u64,
    buf: *const u8,
    len: usize,
    nwritten: *mut usize,
    out: *mut BfsAttr,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, data) = unsafe { (vfs(v)?, bytes(buf, len)?) };
        if u32::try_from(data.len()).is_err() {
            return Err(libc::EINVAL);
        }
        let n = vfs.write_data(ino, offset, data).en()?;
        let a = getattr(vfs, ino)?;
        // SAFETY: guaranteed by the caller.
        unsafe {
            put(nwritten, n as usize);
            put(out, a);
        }
        Ok(())
    })
}

/// A file was opened. Pair with `bfs_open_released`; while any open is
/// outstanding, unlinking the last name keeps the data alive.
///
/// # Safety
/// `v` is a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_open_acquired(v: *const BfsVfs, ino: u64) {
    let _ = guard(|| {
        // SAFETY: guaranteed by the caller.
        unsafe { vfs(v) }?.open_acquired(ino);
        Ok(())
    });
}

/// The open from `bfs_open_acquired` ended; frees the file if it was
/// unlinked meanwhile.
///
/// # Safety
/// `v` is a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_open_released(v: *const BfsVfs, ino: u64) {
    let _ = guard(|| {
        // SAFETY: guaranteed by the caller.
        unsafe { vfs(v) }?.open_released(ino);
        Ok(())
    });
}

// ---------------------------------------------------------------------------
// Extended attributes
// ---------------------------------------------------------------------------

/// # Safety
/// `v` is a live handle; `name` is valid for `len` bytes; `out` is valid
/// for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_get_xattr(
    v: *const BfsVfs,
    ino: u64,
    name: *const u8,
    len: usize,
    out: *mut BfsBuf,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name) = unsafe { (vfs(v)?, self::name(name, len)?) };
        let value = vfs.get_xattr(ino, name).map_err(xattr_errno)?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, into_buf(value)) };
        Ok(())
    })
}

/// Sets an xattr. `mode` is a `BFS_XATTR_*`. Every name is accepted,
/// including `com.apple.*` ones (refusing them breaks `cp -p` and `ditto`).
///
/// # Safety
/// `v` is a live handle; `name` and `value` are valid for their lengths.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_set_xattr(
    v: *const BfsVfs,
    ino: u64,
    name: *const u8,
    len: usize,
    value: *const u8,
    value_len: usize,
    mode: u32,
) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name, value) = unsafe { (vfs(v)?, self::name(name, len)?, bytes(value, value_len)?) };
        if value.len() as u64 > BFS_MAX_XATTR_SIZE {
            return Err(libc::E2BIG);
        }
        let mode = match mode {
            BFS_XATTR_SET => XattrSetMode::CreateOrReplace,
            BFS_XATTR_CREATE => XattrSetMode::CreateOnly,
            BFS_XATTR_REPLACE => XattrSetMode::ReplaceOnly,
            _ => return Err(libc::EINVAL),
        };
        vfs.set_xattr(ino, name, value, mode).map_err(xattr_errno)
    })
}

/// # Safety
/// `v` is a live handle; `name` is valid for `len` bytes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_remove_xattr(v: *const BfsVfs, ino: u64, name: *const u8, len: usize) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let (vfs, name) = unsafe { (vfs(v)?, self::name(name, len)?) };
        vfs.remove_xattr(ino, name).map_err(xattr_errno)
    })
}

/// Lists xattr names as consecutive NUL-terminated strings.
///
/// # Safety
/// `v` is a live handle; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_list_xattrs(v: *const BfsVfs, ino: u64, out: *mut BfsBuf) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let mut all = Vec::new();
        for n in vfs.list_xattrs(ino).en()? {
            all.extend_from_slice(n.as_bytes());
            all.push(0);
        }
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, into_buf(all)) };
        Ok(())
    })
}

/// Frees a buffer returned by this library.
///
/// # Safety
/// `buf` came from this library and is freed only once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_buf_free(buf: BfsBuf) {
    if buf.ptr.is_null() {
        return;
    }
    let slice = std::ptr::slice_from_raw_parts_mut(buf.ptr, buf.len);
    // SAFETY: `buf` was produced by `into_buf` from a boxed slice of `len`.
    drop(unsafe { Box::from_raw(slice) });
}

// ---------------------------------------------------------------------------
// Compression
// ---------------------------------------------------------------------------

/// Compresses every file waiting for compression now; returns how many.
///
/// # Safety
/// `v` is a live handle; `out_count` is null or valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_compact_all(v: *const BfsVfs, out_count: *mut u64) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let vfs = unsafe { vfs(v) }?;
        let n = vfs.compact_all_pending().en()?;
        // SAFETY: guaranteed by the caller.
        unsafe { put(out_count, n as u64) };
        Ok(())
    })
}

/// # Safety
/// `v` is a live handle; `out` is valid for writes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn bfs_compress_stats(v: *const BfsVfs, out: *mut BfsCompressStats) -> i32 {
    guard(|| {
        // SAFETY: guaranteed by the caller.
        let s = unsafe { vfs(v) }?.compress_stats();
        let c = BfsCompressStats {
            compacted: s.compacted,
            inlined: s.inlined,
            rehydrated: s.rehydrated,
            logical_bytes: s.logical_bytes,
            stored_bytes: s.stored_bytes,
            dedup_chunks: s.dedup_chunks,
            dedup_bytes: s.dedup_bytes,
        };
        // SAFETY: guaranteed by the caller.
        unsafe { put(out, c) };
        Ok(())
    })
}
